// คำนวณราคาขายตามนโยบายบริษัท: ส่วนลดตามจำนวน แล้วบวก VAT 7%
const unitPrice = Number(query.unit_price);
const qty = Number(query.qty);
if (!(unitPrice > 0) || !(qty > 0)) {
  return 'ข้อมูลไม่ครบ ต้องมี unit_price และ qty ที่มากกว่า 0';
}
const round2 = (n) => Math.round(n * 100) / 100;
const subtotal = round2(unitPrice * qty);
const discountRate = qty >= 100 ? 10 : qty >= 50 ? 5 : 0;   // 50 ชิ้นขึ้นไปลด 5%, 100 ชิ้นขึ้นไปลด 10%
const discount = round2(subtotal * discountRate / 100);
const net = round2(subtotal - discount);
const vat = round2(net * 0.07);
const total = round2(net + vat);
return JSON.stringify({
  subtotal: subtotal,
  discount_percent: discountRate,
  discount: discount,
  net: net,
  vat_7: vat,
  total_incl_vat: total,
});

