// ราคาพร้อมส่วนลดพิเศษที่เกินนโยบายปกติ (ต้องผ่านการอนุมัติของผู้จัดการก่อนเครื่องมือนี้จะทำงาน)
const unitPrice = Number(query.unit_price);
const qty = Number(query.qty);
const pct = Number(query.discount_percent);
if (!(unitPrice > 0) || !(qty > 0) || !(pct > 0) || pct > 20) {
  return 'ข้อมูลไม่ถูกต้อง ส่วนลดพิเศษต้องอยู่ระหว่าง 1 ถึง 20 เปอร์เซ็นต์';
}
const round2 = (n) => Math.round(n * 100) / 100;
const subtotal = round2(unitPrice * qty);
const discount = round2(subtotal * pct / 100);
const net = round2(subtotal - discount);
const vat = round2(net * 0.07);
return JSON.stringify({ approved_discount_percent: pct, subtotal, discount, net, vat_7: vat, total_incl_vat: round2(net + vat) });

